const wrapper = $input.first().json ?? {};
const event = wrapper.event;
const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const isId = (value) => typeof value === 'string' && value.length >= 1 && value.length <= 64;
const invalid = {
  valid: false,
  eventId: isId(event?.eventId) ? event.eventId : '',
  organizationId: isId(event?.organizationId) ? event.organizationId : '',
  runId: isId(event?.runId) ? event.runId : '',
  errorCode: 'invalid_followup_event',
  errorContext: 'followup',
};
if (!isObject(event) || event.type !== 'conversation.followup_due' || !isId(event.eventId) || !isId(event.organizationId) || !isId(event.runId) || !isObject(event.payload)) {
  return [{ json: invalid }];
}
const payload = event.payload;
if (payload.eventId !== event.eventId || payload.organizationId !== event.organizationId || !isId(payload.conversationId) || typeof payload.scheduledFor !== 'string' || !Number.isFinite(Date.parse(payload.scheduledFor)) || !Number.isInteger(payload.followUpNumber) || payload.followUpNumber < 1 || payload.followUpNumber > 3 || payload.reason !== 'outbound_message_unanswered') {
  return [{ json: invalid }];
}
const actionTimestamp = Date.now();
const actionBody = JSON.stringify({
  eventId: event.eventId,
  runId: event.runId,
  organizationId: event.organizationId,
  conversationId: payload.conversationId,
  timestamp: actionTimestamp,
});
return [{ json: {
  valid: true,
  eventId: event.eventId,
  organizationId: event.organizationId,
  runId: event.runId,
  conversationId: payload.conversationId,
  followUpNumber: payload.followUpNumber,
  actionTimestamp: String(actionTimestamp),
  actionBody,
} }];

const source = $('Prepare follow-up action').first().json;
const response = $input.first().json ?? {};
const statusCode = Number(response.statusCode);
const body = response.body !== null && typeof response.body === 'object' && !Array.isArray(response.body) ? response.body : {};
if (statusCode === 200 && body.ok === true) {
  if (body.callbackRequired === true && ['sent', 'already_sent'].includes(body.state)) {
    return [{ json: {
      decision: 'success',
      eventId: source.eventId,
      organizationId: source.organizationId,
      runId: source.runId,
      actionState: body.state,
      duplicate: body.duplicate === true,
      followUpNumber: source.followUpNumber,
    } }];
  }
  if (body.callbackRequired === false && ['cancelled', 'rescheduled', 'in_progress'].includes(body.state)) {
    return [{ json: {
      decision: 'no_callback',
      eventId: source.eventId,
      organizationId: source.organizationId,
      runId: source.runId,
      actionState: body.state,
    } }];
  }
  return [{ json: {
    decision: 'failure',
    eventId: source.eventId,
    organizationId: source.organizationId,
    runId: source.runId,
    errorCode: 'invalid_action_response',
    errorContext: 'followup',
  } }];
}
if (statusCode === 409 && ['in_progress', 'not_executable'].includes(body.error)) {
  return [{ json: {
    decision: 'no_callback',
    eventId: source.eventId,
    organizationId: source.organizationId,
    runId: source.runId,
    actionState: body.error,
  } }];
}
const errorCode = statusCode === 401
  ? 'action_auth_rejected'
  : statusCode === 404
    ? 'action_not_found'
    : statusCode === 409
      ? 'action_conflict'
      : statusCode === 429
        ? 'action_rate_limited'
        : Number.isInteger(statusCode) && statusCode >= 400 && statusCode < 500
          ? 'action_rejected'
          : 'action_unavailable';
return [{ json: {
  decision: 'failure',
  eventId: source.eventId,
  organizationId: source.organizationId,
  runId: source.runId,
  errorCode,
  errorContext: 'followup',
} }];

const result = $input.first().json;
const callbackTimestamp = Date.now();
const callbackBody = JSON.stringify({
  eventId: result.eventId,
  organizationId: result.organizationId,
  runId: result.runId,
  timestamp: callbackTimestamp,
  status: 'succeeded',
  externalExecutionId: String($execution.id),
  responseMeta: {
    workflow: 'vantix-follow-up',
    actionState: result.actionState,
    duplicate: result.duplicate,
    followUpNumber: result.followUpNumber,
  },
});
return [{ json: { callbackBody, callbackTimestamp: String(callbackTimestamp) } }];
